problems.statement:
For the function below, list every heap allocation and every copy, then rewrite it to be allocation- and copy-free on the hot path:

```
std::vector<std::string> hot(std::vector<std::string> names, std::string prefix) {
    std::vector<std::string> out;
    for (std::string n : names) {
        std::string label = prefix + n;
        out.push_back(label);
    }
    return out;
}
```

codes.source:
std::vector<std::string> hot(const std::vector<std::string>& names,
                             std::string_view prefix) {   // no input copies
    std::vector<std::string> out;
    out.reserve(names.size());                  // one allocation, no growth churn
    for (const std::string& n : names) {        // no per-element copy
        std::string label;
        label.reserve(prefix.size() + n.size()); // build in place, no '+' temporary
        label.append(prefix).append(n);
        out.push_back(std::move(label));          // move into the vector, no copy
    }
    return out;                                  // NRVO / move, not a copy
}
